def transform_v3(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    shape_color = 8
    fill_color = 4
    background_color = 6

    result = [row[:] for row in grid]

    # For each row, find gaps (sequences of background color)
    for r in range(rows):
        gap_start = 0
        for c in range(cols):
            if grid[r][c] == background_color:
                # Find end of gap
                gap_end = c
                while gap_end < cols and grid[r][gap_end] == background_color:
                    gap_end += 1

                # Gap is from c to gap_end-1
                # Check if all cells above (r-1) and below (r+1) in this gap range have shape_color
                if r > 0 and r + 1 < rows:  # has both above and below
                    all_above = all(grid[r-1][gc] == shape_color for gc in range(c, gap_end))
                    all_below = all(grid[r+1][gc] == shape_color for gc in range(c, gap_end))

                    if all_above and all_below:
                        for gc in range(c, gap_end):
                            result[r][gc] = fill_color

                c = gap_end - 1
            else:
                c += 1

    return result

