def transform_added_rule(grid, fg_color=8, bg_color=6, fill_color=4):
    """
    Rule: For each column, if there are multiple segments of fg_color,
    fill bg cells between consecutive segments ONLY if the column is
    within the "interior" of the overall shape's horizontal bounds.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # First, find overall horizontal bounds of the shape
    leftmost_col = None
    rightmost_col = None
    for c in range(cols):
        for r in range(rows):
            if grid[r][c] == fg_color:
                if leftmost_col is None:
                    leftmost_col = c
                rightmost_col = c

    result = [row[:] for row in grid]

    for c in range(cols):
        if leftmost_col is None:  # No shape
            continue

        # Find segments in this column
        in_seg = False
        segments = []
        for r in range(rows):
            if grid[r][c] == fg_color:
                if not in_seg:
                    in_seg = True
                    segments.append([r])
            else:
                if in_seg:
                    in_seg = False

        # Apply filling rule
        if len(segments) >= 2 and leftmost_col < c < rightmost_col:
            for i in range(len(segments) - 1):
                seg1_end = segments[i][-1]
                seg2_start = segments[i+1][0]
                for r in range(seg1_end + 1, seg2_start):
                    if grid[r][c] == bg_color:
                        result[r][c] = fill_color

    return result

