def transform_new_rule(grid, fg=5, bg=6, fill=4):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    result = [row[:] for row in grid]

    # Step 1: For each column, detect segments and gaps
    col_data = {}  # col -> (segments, gap_rows)
    for c in range(cols):
        in_seg = False
        segments = []
        for r in range(rows):
            if grid[r][c] == fg:
                if not in_seg:
                    in_seg = True
                    segments.append([r])
            else:
                if in_seg:
                    in_seg = False

        gap_rows = []
        if len(segments) >= 2:
            for i in range(len(segments) - 1):
                seg1_end = segments[i][-1]
                seg2_start = segments[i+1][0]
                gap_rows.extend(range(seg1_end + 1, seg2_start))

        col_data[c] = {'segments': segments, 'gap_rows': gap_rows}

    # Step 2: Find non-adjacent columns that have segments in gap rows
    # For each multi-gap column, check left and right non-adjacent cols
    for c in range(cols):
        if c not in col_data or len(col_data[c]['gap_rows']) == 0:
            continue

        left_can_fill = False
        right_can_fill = False

        # Check left non-adjacent columns (c-2, c-3, etc.) that have segments in gap_rows
        for delta in range(2, c):
            if delta - 1 < 0:  # c-2 is left boundary, handle wrap
                break
            left_col = c - delta
            if left_col < 0 or left_col >= cols:
                continue
            left_has_segment_in_gap = any(
                r in seg for seg in col_data[left_col]['segments'] 
                for r in col_data[c]['gap_rows']
            )
            if left_has_segment_in_gap:
                left_can_fill = True
                break

        # Check right non-adjacent columns (c+2, c+3, etc.)
        for delta in range(2, cols - c):
            right_col = c + delta
            if right_col >= cols:
                continue
            right_has_segment_in_gap = any(
                r in seg for seg in col_data[right_col]['segments'] 
                for r in col_data[c]['gap_rows']
            )
            if right_has_segment_in_gap:
                right_can_fill = True
                break

        # Only fill if BOTH sides have segments in the gap rows
        if left_can_fill and right_can_fill:
            for r in col_data[c]['gap_rows']:
                if grid[r][c] == bg:
                    result[r][c] = fill

    return result

